    for label in labels:
        analyze_request = {
            "comment": {"text": label},
            "requestedAttributes": {
                "TOXICITY": {},
                "SEVERE_TOXICITY": {},
                "IDENTITY_ATTACK": {},
                "INSULT": {},
                "PROFANITY": {},
                "THREAT": {},
            },
        }
        response = client.comments().analyze(body=analyze_request).execute()
        results.append({"label": label, "attributes": response["attributeScores"]})
    return results
